import{_ as r,C as l,o as e,c as d,j as i,a as n,E as t,a3 as s}from"./chunks/framework.C6R8kWFE.js";const D=JSON.parse('{"title":"10-dars (Mentor). Internet qanday ishlaydi? IP, hosting, domen, DNS, brauzer, HTTP/HTTPS","description":"","frontmatter":{"title":"10-dars (Mentor). Internet qanday ishlaydi? IP, hosting, domen, DNS, brauzer, HTTP/HTTPS","layout":"doc","sidebar":false,"aside":false,"outline":false,"kind":"mentor_dars","dars":{"sinf":{"name":"8-sinf (Foundation)","link":"/mentor/8-sinf-cs/"},"week":{"n":4,"link":"/mentor/8-sinf-cs/hafta-04/"},"g":10,"title":"Internet qanday ishlaydi? IP, hosting, domen, DNS, brauzer, HTTP/HTTPS","lead":"Siz brauzerga manzil yozasiz va bir soniyada sahifa ochiladi. Bu orada IP, DNS, hosting va HTTPS qanday ishlaydi? Bugun internetning «ichki dunyosi»ga kiramiz.","slide":"/slaydlar/8-sinf-cs/hafta-04/dars-1.html","test":"/slaydlar/8-sinf-cs/hafta-04/dars-1-test.html","student_link":"/8-sinf-cs/hafta-04/dars-1","tabs":[{"g":10,"link":"/mentor/8-sinf-cs/hafta-04/dars-1","current":true},{"g":11,"link":"/mentor/8-sinf-cs/hafta-04/dars-2","current":false},{"g":12,"link":"/mentor/8-sinf-cs/hafta-04/dars-3","current":false}],"prev":null,"next":{"g":11,"title":"Bulutli xizmatlar va onlayn hamkorlik vositalari (1-qism): bulutli saqlash, yuklash va ulashish","link":"/mentor/8-sinf-cs/hafta-04/dars-2"}}},"headers":[],"relativePath":"mentor/8-sinf-cs/hafta-04/dars-1.md","filePath":"mentor/8-sinf-cs/hafta-04/dars-1.md"}'),h={name:"mentor/8-sinf-cs/hafta-04/dars-1.md"},m={class:"blk"},u={id:"_1-dars-rejasi",tabindex:"-1"},g={class:"blk"},b={id:"_2-dars-konspekti",tabindex:"-1"},c={class:"blk"},p={id:"_3-amaliy-mashg-ulotlar",tabindex:"-1"},y={class:"blk"},v={id:"_4-tezkor-savollar-checklist",tabindex:"-1"},q={class:"blk"},k={id:"_5-kuchli-o-quvchi-uchun-qo-shimcha",tabindex:"-1"},z={class:"blk"},f={id:"_6-mentor-uchun-eslatmalar",tabindex:"-1"};function T(P,a,x,_,S,I){const o=l("Icon");return e(),d("div",null,[a[18]||(a[18]=i("p",null,[i("strong",null,"Hafta:"),n(" 4 · "),i("strong",null,"Davomiyligi:"),n(" 80 daqiqa · "),i("strong",null,"Turi:"),n(" nazariya + tadqiqot amaliyoti · "),i("strong",null,"II-bob"),n(", 4-dars (hafta ichida 1-dars)")],-1)),a[19]||(a[19]=i("blockquote",null,[i("p",null,"Manba: o'quv dasturi, 10-mavzu: «Internet tushunchasi va ma'lumot almashish jarayoni. IP-manzil, domen nomi va hosting tushunchalari. DNS vazifasi va domenni IP-manzilga bog'lash jarayoni. Brauzer va veb-sahifani ochish bosqichlari. HTTP va HTTPS protokollari hamda xavfsiz ulanish.» Dasturda boshqa tafsilot yo'q; quyidagi tushuntirishlar shu bandlarni sodda tilda ochib beradi.")],-1)),i("div",m,[i("h2",u,[t(o,{name:"file-text"}),a[0]||(a[0]=n(" 1. Dars rejasi ",-1)),a[1]||(a[1]=i("a",{class:"header-anchor",href:"#_1-dars-rejasi","aria-label":'Permalink to "<Icon name="file-text" /> 1. Dars rejasi"'},"​",-1))]),a[2]||(a[2]=s('<p><strong>Maqsad:</strong> o&#39;quvchilar internetning ma&#39;lumot almashish jarayonini (so&#39;rov va javob) tushunadi; IP-manzil, domen, hosting va DNS ning vazifasini farqlaydi; brauzerda veb-sahifa ochilish bosqichlarini tartib bilan aytadi; HTTP va HTTPS farqini va xavfsiz ulanish belgisini biladi.</p><p><strong>Kutiladigan natija:</strong></p><ul><li>Internetni «tarmoqlar tarmog&#39;i» deb ta&#39;riflay oladi, mijoz (client) va server rolini ajratadi.</li><li>IP-manzil, domen, hosting, DNS ni hayotiy o&#39;xshatish bilan tushuntiradi.</li><li>Havola (URL) tarkibini bo&#39;laklarga ajratadi.</li><li>Veb-sahifa ochilishining 5 bosqichini tartib bilan aytadi.</li><li>HTTPS saytni brauzerdagi belgi orqali taniydi va parol kiritishdan oldin tekshiradi.</li></ul><table tabindex="0"><thead><tr><th>Vaqt</th><th>Bosqich</th><th>Mazmun</th></tr></thead><tbody><tr><td>0–10 daq</td><td>Takrorlash va kirish</td><td>9-dars (raqamli transformatsiya) ni qisqa takrorlash. Savol: «my.gov.uz ga kirganda kompyuteringiz 1 soniyada nima qiladi?» — o&#39;quvchilar taxmin qiladi</td></tr><tr><td>10–35 daq</td><td>Yangi mavzu</td><td>Internet, IP, domen, hosting, DNS, brauzer, HTTP/HTTPS</td></tr><tr><td>35–40 daq</td><td>Tanaffus</td><td>Harakatli tanaffus</td></tr><tr><td>40–65 daq</td><td>Amaliy mashg&#39;ulot</td><td>Havola anatomiyasi, bosqichlarni tartiblash, HTTPS tekshiruvi, «DNS» rol o&#39;yini</td></tr><tr><td>65–75 daq</td><td>Tezkor nazorat</td><td>5 ta savol + mini-viktorina</td></tr><tr><td>75–80 daq</td><td>Xulosa va uyga vazifa</td><td>Xulosa, uyga vazifa yo&#39;riqnomasi</td></tr></tbody></table><hr>',5))]),i("div",g,[i("h2",b,[t(o,{name:"file-text"}),a[3]||(a[3]=n(" 2. Dars konspekti ",-1)),a[4]||(a[4]=i("a",{class:"header-anchor",href:"#_2-dars-konspekti","aria-label":'Permalink to "<Icon name="file-text" /> 2. Dars konspekti"'},"​",-1))]),a[5]||(a[5]=s(`<h3 id="_2-1-internet-nima-va-ma-lumot-qanday-almashiladi" tabindex="-1">2.1. Internet nima va ma&#39;lumot qanday almashiladi? <a class="header-anchor" href="#_2-1-internet-nima-va-ma-lumot-qanday-almashiladi" aria-label="Permalink to &quot;2.1. Internet nima va ma&#39;lumot qanday almashiladi?&quot;">​</a></h3><p><strong>Internet</strong> — dunyo bo&#39;ylab millionlab kompyuter, telefon va serverlarni bir-biriga ulaydigan global tarmoq. Shuning uchun uni «tarmoqlar tarmog&#39;i» deb ataydilar.</p><p>Ma&#39;lumot almashish doim bir xil qoida bo&#39;yicha ketadi:</p><ul><li><strong>Mijoz (client)</strong> — siz foydalanadigan qurilma (telefon, kompyuter) va unda ishlaydigan dastur (brauzer).</li><li><strong>Server</strong> — doim yoqilgan, internetga ulangan va so&#39;ralgan ma&#39;lumotni beradigan kompyuter.</li><li><strong>So&#39;rov (request)</strong> — mijoz serverdan nimadir so&#39;raydi.</li><li><strong>Javob (response)</strong> — server so&#39;ralgan narsani qaytaradi.</li></ul><blockquote><p>O&#39;xshatish (qo&#39;shimcha): restoranda siz (mijoz) ofitsiantga buyurtma berasiz (so&#39;rov), oshxona (server) taomni tayyorlab beradi (javob).</p></blockquote><h3 id="_2-2-ip-manzil" tabindex="-1">2.2. IP-manzil <a class="header-anchor" href="#_2-2-ip-manzil" aria-label="Permalink to &quot;2.2. IP-manzil&quot;">​</a></h3><p><strong>IP-manzil (IP address)</strong> — tarmoqdagi har bir qurilmaning noyob raqamli manzili. Internetda ma&#39;lumot aynan shu manzil bo&#39;yicha topiladi. Ko&#39;rinishi: to&#39;rtta son nuqta bilan ajratilgan (IPv4), har biri 0 dan 255 gacha.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes light-plus dark-plus vp-code" tabindex="0"><code><span class="line"><span>192.168.1.10       &lt;- uy Wi-Fi tarmog&#39;idagi qurilma manzili (ichki manzil misoli)</span></span>
<span class="line"><span>203.0.113.5        &lt;- ko&#39;rgazma uchun ajratilgan namuna manzil</span></span></code></pre></div><blockquote><p>O&#39;xshatish: IP — uyning aniq pochta indeksi va raqami: manzilsiz xat yetib bormaydi.</p></blockquote><p>Muammo: odam uchun <code>203.0.113.5</code> kabi raqamlarni yodlash qiyin. Shuning uchun domen nomi paydo bo&#39;lgan.</p><h3 id="_2-3-domen-nomi" tabindex="-1">2.3. Domen nomi <a class="header-anchor" href="#_2-3-domen-nomi" aria-label="Permalink to &quot;2.3. Domen nomi&quot;">​</a></h3><p><strong>Domen nomi (domain name)</strong> — IP-manzil o&#39;rniga ishlatiladigan, odam eslab qoladigan nom, masalan <code>my.gov.uz</code>, <code>wikipedia.org</code>.</p><p>Domen tuzilishi (o&#39;ngdan chapga o&#39;qiladi):</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes light-plus dark-plus vp-code" tabindex="0"><code><span class="line"><span>https://www.maktab.uz/kutubxona/kitoblar.html</span></span>
<span class="line"><span>  |      |    |     |      |</span></span>
<span class="line"><span>protokol sub- nom  zona   yo&#39;l (sahifa manzili)</span></span>
<span class="line"><span>         domen</span></span></code></pre></div><ul><li><strong>Zona (TLD):</strong> <code>.uz</code> (O&#39;zbekiston), <code>.com</code>, <code>.org</code>, <code>.edu</code>.</li><li><strong>Domen nomi:</strong> <code>maktab</code>.</li><li><strong>Subdomen:</strong> <code>www</code> yoki <code>mail</code> kabi old qism.</li><li><strong>Yo&#39;l:</strong> serverdagi aniq sahifa.</li></ul><p>Domenni <strong>ro&#39;yxatdan o&#39;tkazish</strong> kerak (har yili haq to&#39;lanadi) — ikki kishi bir xil domenga ega bo&#39;la olmaydi.</p><h3 id="_2-4-hosting" tabindex="-1">2.4. Hosting <a class="header-anchor" href="#_2-4-hosting" aria-label="Permalink to &quot;2.4. Hosting&quot;">​</a></h3><p><strong>Hosting</strong> — veb-sayt fayllari (HTML, rasm, video) saqlanadigan va internetga 24/7 ochiq turadigan server (yoki server joyini ijaraga berish xizmati).</p><blockquote><p>O&#39;xshatish: <strong>domen</strong> — do&#39;konning nomi (peshtaxta), <strong>hosting</strong> — do&#39;konning o&#39;zi (bino va javonlar), <strong>IP</strong> — do&#39;konning aniq manzili.</p></blockquote><p>Sayt kompyuteringizda emas, hosting serverida turadi; shuning uchun o&#39;chirilgan kompyuter ham saytni ko&#39;rsatishga xalaqit qilmaydi.</p><h3 id="_2-5-dns" tabindex="-1">2.5. DNS <a class="header-anchor" href="#_2-5-dns" aria-label="Permalink to &quot;2.5. DNS&quot;">​</a></h3><p><strong>DNS (Domain Name System)</strong> — domen nomini IP-manzilga aylantiruvchi xizmat. Uni internetning «telefon kitobi» deb ataydilar: ismni (domen) qidirasiz, raqamni (IP) olasiz.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes light-plus dark-plus vp-code" tabindex="0"><code><span class="line"><span>brauzer:  &quot;my.gov.uz manzili qanday?&quot;</span></span>
<span class="line"><span>DNS:      &quot;203.0.113.5&quot;   (namuna)</span></span>
<span class="line"><span>brauzer:  203.0.113.5 ga ulanadi</span></span></code></pre></div><p>DNS javobi bo&#39;lmasa, sayt ishlayotgan bo&#39;lsa ham siz uni nom bilan topa olmaysiz.</p><h3 id="_2-6-brauzer-va-veb-sahifaning-ochilishi" tabindex="-1">2.6. Brauzer va veb-sahifaning ochilishi <a class="header-anchor" href="#_2-6-brauzer-va-veb-sahifaning-ochilishi" aria-label="Permalink to &quot;2.6. Brauzer va veb-sahifaning ochilishi&quot;">​</a></h3><p><strong>Brauzer</strong> (Chrome, Edge, Firefox, Safari) — veb-sahifani so&#39;raydigan va ko&#39;rsatadigan dastur. Sahifa ochilishining 5 bosqichi:</p><ol><li>Manzilni yozasiz yoki havolani bosasiz (<code>https://www.maktab.uz</code>).</li><li>Brauzer DNS dan domenga mos IP-manzilni so&#39;raydi.</li><li>Brauzer shu IP dagi serverga ulanadi va sahifani so&#39;raydi (HTTP/HTTPS so&#39;rovi).</li><li>Server fayllarni (HTML, CSS, rasmlar) javob sifatida yuboradi.</li><li>Brauzer fayllarni yig&#39;ib, sahifani ekranda chizadi.</li></ol><h3 id="_2-7-http-va-https" tabindex="-1">2.7. HTTP va HTTPS <a class="header-anchor" href="#_2-7-http-va-https" aria-label="Permalink to &quot;2.7. HTTP va HTTPS&quot;">​</a></h3><p><strong>Protokol</strong> — ikki kompyuter bir-birini tushunishi uchun kelishilgan qoidalar to&#39;plami.</p><ul><li><strong>HTTP (HyperText Transfer Protocol)</strong> — veb-sahifalarni uzatish qoidalari. Ma&#39;lumot shifrlanmagan holda ketadi: yo&#39;ldagi begona odam o&#39;qib olishi mumkin.</li><li><strong>HTTPS (HTTP Secure)</strong> — HTTP + shifrlash. Ma&#39;lumot shifrlangan holda uzatiladi, server esa sertifikat orqali o&#39;zini tasdiqlaydi. Brauzerda qulf belgisi va <code>https://</code> ko&#39;rinadi.</li></ul><table tabindex="0"><thead><tr><th></th><th>HTTP</th><th>HTTPS</th></tr></thead><tbody><tr><td>Shifrlash</td><td>yo&#39;q</td><td>bor</td></tr><tr><td>Brauzerda</td><td><code>http://</code>, ko&#39;pincha «Xavfsiz emas» belgisi</td><td><code>https://</code>, qulf belgisi</td></tr><tr><td>Qayerda kerak</td><td>ochiq, shaxsiy ma&#39;lumotsiz sahifalar</td><td>parol, karta, shaxsiy ma&#39;lumot kiritiladigan har qanday sahifa</td></tr></tbody></table><p>Muhim qoida: HTTPS saytning o&#39;zi «yaxshi sayt» degani emas, faqat ulanish shifrlanganini bildiradi. Sayt manzilini (domen to&#39;g&#39;ri yozilganini) ham tekshiring.</p><h3 id="_2-8-butun-rasm" tabindex="-1">2.8. Butun rasm <a class="header-anchor" href="#_2-8-butun-rasm" aria-label="Permalink to &quot;2.8. Butun rasm&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes light-plus dark-plus vp-code" tabindex="0"><code><span class="line"><span>Siz -&gt; brauzer -&gt; DNS (nom -&gt; IP) -&gt; hosting serveri (HTTPS so&#39;rov) -&gt; javob -&gt; brauzer sahifani chizadi</span></span></code></pre></div><h3 id="_2-9-ixtiyoriy-demo-dasturda-yo-q-mentor-xohlasa" tabindex="-1">2.9. Ixtiyoriy demo (dasturda yo&#39;q, mentor xohlasa) <a class="header-anchor" href="#_2-9-ixtiyoriy-demo-dasturda-yo-q-mentor-xohlasa" aria-label="Permalink to &quot;2.9. Ixtiyoriy demo (dasturda yo&#39;q, mentor xohlasa)&quot;">​</a></h3><p>Windows buyruq satrida (Win + R, <code>cmd</code>) domen IP ga qanday aylanishini ko&#39;rsatish mumkin:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes light-plus dark-plus vp-code" tabindex="0"><code><span class="line"><span>nslookup wikipedia.org</span></span>
<span class="line"><span>ping wikipedia.org</span></span></code></pre></div><p><code>nslookup</code> DNS javobini (IP-manzil) ko&#39;rsatadi; <code>ping</code> serverga signal yuborib, javob kelishini tekshiradi. Natija har kuni va har joyda har xil bo&#39;lishi mumkin. Maktab tarmog&#39;ida buyruqlar cheklangan bo&#39;lsa, o&#39;tkazib yuboring.</p><hr>`,39))]),i("div",c,[i("h2",p,[t(o,{name:"file-text"}),a[6]||(a[6]=n(" 3. Amaliy mashg'ulotlar ",-1)),a[7]||(a[7]=i("a",{class:"header-anchor",href:"#_3-amaliy-mashg-ulotlar","aria-label":`Permalink to "<Icon name="file-text" /> 3. Amaliy mashg'ulotlar"`},"​",-1))]),a[8]||(a[8]=s('<h3 id="_1-mashq-oson-havola-anatomiyasi" tabindex="-1">1-mashq (oson). Havola anatomiyasi <a class="header-anchor" href="#_1-mashq-oson-havola-anatomiyasi" aria-label="Permalink to &quot;1-mashq (oson). Havola anatomiyasi&quot;">​</a></h3><p><strong>Vazifa:</strong> <code>https://www.kitobxona.uz/bolalar/ertaklar.html</code> havolasini bo&#39;laklarga ajrating: protokol, subdomen, domen nomi, zona, yo&#39;l.</p><p><strong>Yechim:</strong></p><ul><li>protokol: <code>https</code></li><li>subdomen: <code>www</code></li><li>domen nomi: <code>kitobxona</code></li><li>zona: <code>.uz</code></li><li>yo&#39;l: <code>/bolalar/ertaklar.html</code></li></ul><h3 id="_2-mashq-oson-bosqichlarni-tartiblash" tabindex="-1">2-mashq (oson). Bosqichlarni tartiblash <a class="header-anchor" href="#_2-mashq-oson-bosqichlarni-tartiblash" aria-label="Permalink to &quot;2-mashq (oson). Bosqichlarni tartiblash&quot;">​</a></h3><p><strong>Vazifa:</strong> Quyidagi bosqichlarni to&#39;g&#39;ri tartibga soling: (a) brauzer sahifani chizadi, (b) DNS IP-manzilni qaytaradi, (c) server fayllarni yuboradi, (d) foydalanuvchi domenni yozadi, (e) brauzer serverga so&#39;rov yuboradi.</p><p><strong>Yechim:</strong> d → b → e → c → a. (Avval nom yoziladi, DNS manzil topadi, so&#39;rov ketadi, server javob beradi, brauzer chizadi.)</p><h3 id="_3-mashq-o-rta-https-tekshiruvi" tabindex="-1">3-mashq (o&#39;rta). HTTPS tekshiruvi <a class="header-anchor" href="#_3-mashq-o-rta-https-tekshiruvi" aria-label="Permalink to &quot;3-mashq (o&#39;rta). HTTPS tekshiruvi&quot;">​</a></h3><p><strong>Vazifa:</strong> Brauzerda 3 ta saytni oching (masalan, <code>my.gov.uz</code>, <code>wikipedia.org</code> va maktabingiz yoki sevimli saytingiz). Har biri uchun jadvalni to&#39;ldiring: manzil <code>https://</code> bilan boshlanadimi? Qulf belgisi bormi?</p><p><strong>Yechim:</strong> natija saytga bog&#39;liq. Ko&#39;pchilik zamonaviy saytlar HTTPS da. Muhimi — o&#39;quvchi manzil satri chap qismidagi belgini topa olishi va izohlay olishi. Agar <code>http://</code> va «Xavfsiz emas» belgisi chiqsa, shu saytda parol kiritmaslik kerakligini aytsin.</p><h3 id="_4-mashq-o-rta-rol-o-yini-«dns»" tabindex="-1">4-mashq (o&#39;rta). Rol o&#39;yini: «DNS» <a class="header-anchor" href="#_4-mashq-o-rta-rol-o-yini-«dns»" aria-label="Permalink to &quot;4-mashq (o&#39;rta). Rol o&#39;yini: «DNS»&quot;">​</a></h3><p><strong>Vazifa:</strong> Sinfdagi bir o&#39;quvchi — DNS (daftarida 5 ta domen va IP-raqam yozilgan «telefon kitobi»), ikkinchisi — brauzer, uchinchisi — server. Brauzer domenni so&#39;raydi, DNS IP ni aytadi, brauzer serverga «so&#39;rov» yozuvini topshiradi, server «sahifa» qog&#39;ozini qaytaradi. Rollarni almashtirib 3 marta takrorlang.</p><p><strong>Yechim:</strong> o&#39;yin davomida tartib: so&#39;rov → DNS → IP → server → javob. O&#39;quvchilar DNS «qidiruv» vazifasini, serverning «javob» vazifasini farqlay olsin.</p><h3 id="_5-mashq-qiyin-hayotiy-o-xshatish-jadvali" tabindex="-1">5-mashq (qiyin). Hayotiy o&#39;xshatish jadvali <a class="header-anchor" href="#_5-mashq-qiyin-hayotiy-o-xshatish-jadvali" aria-label="Permalink to &quot;5-mashq (qiyin). Hayotiy o&#39;xshatish jadvali&quot;">​</a></h3><p><strong>Vazifa:</strong> Domen, IP, hosting, DNS, brauzer, server uchun shahar hayotidan o&#39;xshatish toping (masalan, do&#39;kon, manzil, telefon kitobi) va jadval tuzing.</p><p><strong>Yechim:</strong> (namuna) domen — do&#39;kon nomi; IP — aniq manzil; hosting — do&#39;kon binosi; DNS — telefon kitobi/navigator; brauzer — xaridor; server — sotuvchi. Boshqa mantiqli o&#39;xshatishlar ham qabul.</p><hr>',17))]),i("div",y,[i("h2",v,[t(o,{name:"file-text"}),a[9]||(a[9]=n(" 4. Tezkor savollar (Checklist) ",-1)),a[10]||(a[10]=i("a",{class:"header-anchor",href:"#_4-tezkor-savollar-checklist","aria-label":'Permalink to "<Icon name="file-text" /> 4. Tezkor savollar (Checklist)"'},"​",-1))]),a[11]||(a[11]=s("<ol><li>IP-manzil nima? <ul><li><strong>Javob:</strong> Tarmoqdagi qurilmaning noyob raqamli manzili.</li></ul></li><li>Domen nomi nima uchun kerak? <ul><li><strong>Javob:</strong> IP-raqamlarni yodlash o&#39;rniga odam uchun oson, eslab qoladigan nom bo&#39;lishi uchun.</li></ul></li><li>Hosting nima? <ul><li><strong>Javob:</strong> Sayt fayllari saqlanadigan va doim internetga ochiq turadigan server (yoki shu xizmat).</li></ul></li><li>DNS ning vazifasi nima? <ul><li><strong>Javob:</strong> Domen nomini IP-manzilga aylantirish.</li></ul></li><li>HTTP va HTTPS ning asosiy farqi nima? <ul><li><strong>Javob:</strong> HTTPS ma&#39;lumotni shifrlaydi, HTTP shifrlamaydi.</li></ul></li></ol>",1))]),i("div",q,[i("h2",k,[t(o,{name:"file-text"}),a[12]||(a[12]=n(" 5. Kuchli o'quvchi uchun qo'shimcha ",-1)),a[13]||(a[13]=i("a",{class:"header-anchor",href:"#_5-kuchli-o-quvchi-uchun-qo-shimcha","aria-label":`Permalink to "<Icon name="file-text" /> 5. Kuchli o'quvchi uchun qo'shimcha"`},"​",-1))]),a[14]||(a[14]=i("ul",null,[i("li",null,"Bir saytga bir nechta domen bog'lash mumkinmi? (Ha: bir hosting, bir necha domen.)"),i("li",null,"Bitta IP ga bir nechta sayt joylashishi mumkinmi? (Ha, bitta serverda bir necha sayt turishi mumkin.)")],-1))]),i("div",z,[i("h2",f,[t(o,{name:"file-text"}),a[15]||(a[15]=n(" 6. Mentor uchun eslatmalar ",-1)),a[16]||(a[16]=i("a",{class:"header-anchor",href:"#_6-mentor-uchun-eslatmalar","aria-label":'Permalink to "<Icon name="file-text" /> 6. Mentor uchun eslatmalar"'},"​",-1))]),a[17]||(a[17]=i("ul",null,[i("li",null,"Dasturda IPv6, portlar, sertifikat turlari yo'q: chuqurlashmang, faqat savol bo'lsa qisqa javob bering."),i("li",null,[n("IP raqamlari uchun namuna ("),i("code",null,"203.0.113.x"),n(") ishlatilgan: bu aniq sayt emas, deb ayting.")]),i("li",null,"Maktab tarmog'ida ba'zi saytlar yopiq bo'lishi mumkin; zaxira sayt: o'quvchilarga ma'lum bo'lgan istalgan HTTPS sayt.")],-1))])])}const j=r(h,[["render",T]]);export{D as __pageData,j as default};
